* LICENSE file in the root directory of this source tree.
*/
const SideNavItem = ({ className: customClassName, children, large = false }) => {
	const prefix = usePrefix();
	const className = cx({
		[`${prefix}--side-nav__item`]: true,
		[`${prefix}--side-nav__item--large`]: large,
		[customClassName]: !!customClassName
	});
	return /* @__PURE__ */ jsx("li", {
		className,
		children
	});
};
SideNavItem.propTypes = {
	/**
	* Provide a single icon as the child to `SideNavItem` to render in the
	* container
	*/
	children: PropTypes.node.isRequired,
	/**
	* Provide an optional class to be applied to the containing node
	*/
	className: PropTypes.string,
	/**
	* Specify if this is a large variation of the SideNavItem
	*/
	large: PropTypes.bool
};
//#endregion
export { SideNavItem as default };
